import sys

def main():
    data = sys.stdin.read().split()
    s = data[0]
    need = set(data[1])
    k = len(need)
    cnt = {c: 0 for c in need}
    have = 0
    l = 0
    ans = 0
    for ch in s:
        if ch in cnt:
            cnt[ch] += 1
            if cnt[ch] == 1:
                have += 1
        while have == k:
            c = s[l]
            if c in cnt:
                cnt[c] -= 1
                if cnt[c] == 0:
                    have -= 1
            l += 1
        ans += l
    print(ans)

